// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {FlashGovernanceArbiter} from "../src/FlashGovernanceArbiter.sol";

contract InvMutTest is Test {
    FlashGovernanceArbiter c;
    __InvMutHandleStub dao;

    function setUp() public {
        dao = new __InvMutHandleStub();
        c = new FlashGovernanceArbiter(address(dao));
    }

    function testFuzz_property(uint256 depositAmount, uint256 warpDelta, address target, address user) public {
        vm.assume(user != address(0) && target != address(0));
        depositAmount = bound(depositAmount, 1, 1e30);
        warpDelta = bound(warpDelta, 1, 1e18);

        // configure flash governance: asset = stub (its transferFrom always succeeds), unlockTime 0
        vm.prank(address(dao));
        c.configureFlashGovernance(address(dao), depositAmount, 0, false);

        // DAO triggers a flash governance deposit on behalf of user for target
        vm.prank(address(dao));
        c.assertGovernanceApproved(user, target, true);

        // let the unlock time pass
        vm.warp(block.timestamp + warpDelta);

        // the owner withdraws the pending governance asset
        vm.prank(user);
        bool ok;
        try c.withdrawGovernanceAsset(target, address(dao)) {
            ok = true;
        } catch {
            ok = false;
        }

        (uint256 pendingAmount, , , ) = c.pendingFlashDecision(target, user);
        assertTrue(ok && pendingAmount == 0);
    }
}

contract __InvMutHandleStub {
    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
    function underlying() external view returns (address) { return address(this); }
    function WETH() external view returns (address) { return address(this); }
    function name() external pure returns (string memory) { return "S"; }
